def _parse_interval_range(interval_value):
    """Accepts a fixed number of minutes, or a "min-max" range string like
    "2-5", and returns a (min_minutes, max_minutes) tuple."""
    if isinstance(interval_value, str):
        parts = interval_value.split('-')
        if len(parts) != 2:
            raise ValueError(f"Invalid interval range {interval_value!r}, expected format 'min-max' e.g. '2-5'")
        low, high = float(parts[0].strip()), float(parts[1].strip())
        if low > high:
            low, high = high, low
        return low, high

    value = float(interval_value)
    return value, value

def _interval_enabled(interval_value):
    if interval_value is None:
        return False
    try:
        low, high = _parse_interval_range(interval_value)
    except (ValueError, TypeError):
        return False
    return high > 0

def _random_interval_seconds(interval_value):
    low, high = _parse_interval_range(interval_value)
    minutes = random.uniform(low, high)
    return max(5, minutes * 60)

