async def wait_for_streams(streamer_names):
    """Watch a batch of offline streamers together: check all of them, sleep
    5 seconds, check all of them again, etc. As soon as one goes live its
    handle_streamer() is kicked off in the background (so it doesn't block
    the rest of the batch), and it drops out of the list. Runs quietly -
    only logs once per batch on start and once per streamer when it comes
    online, instead of announcing every single check."""
    remaining = list(dict.fromkeys(streamer_names))  # dedupe, keep order
    if not remaining:
        return

    api = KickAPI(config['Private']['token'])
    logger.info(f"[WAITING] {', '.join(remaining)} - waiting for stream(s) to start...")

    while remaining:
        try:
            still_offline = []
            for name in remaining:
                try:
                    if api.is_stream_live(name):
                        logger.info(f"[ONLINE] {name} is now live!")
                        asyncio.create_task(handle_streamer({"name": name}))
                    else:
                        still_offline.append(name)
                except asyncio.CancelledError:
                    raise
                except Exception:
                    traceback.print_exc()
                    still_offline.append(name)

            remaining = still_offline
            if remaining:
                await asyncio.sleep(5)  # one shared sleep for the whole batch
        except asyncio.CancelledError:
            break

